INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (9, 'M09.10', 'Exam Question Bank', 10)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which statement best describes the importance of human factors in aircraft maintenance?', '[{"id": "a", "text": "They are insignificant.", "correct": false}, {"id": "b", "text": "They are a significant safety concern.", "correct": true}, {"id": "c", "text": "They only matter on older aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Murphy''s law is perpetuated mainly by.', '[{"id": "a", "text": "violations.", "correct": false}, {"id": "b", "text": "poor aircraft design.", "correct": false}, {"id": "c", "text": "complacency.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Murphy''s law can be regarded as the notion.', '[{"id": "a", "text": "If something can go wrong it will''.", "correct": true}, {"id": "b", "text": "It can never happen to me''.", "correct": false}, {"id": "c", "text": "If something goes wrong I am certain to get the blame''.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A company''s safety policy should be defined in.', '[{"id": "a", "text": "in CAP 716.", "correct": false}, {"id": "b", "text": "the Maintenance Schedule.", "correct": false}, {"id": "c", "text": "the Maintenance Organization Exposition.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which topic is directly associated with human factors?', '[{"id": "a", "text": "Ergonomics, health and safety, and human error.", "correct": true}, {"id": "b", "text": "Only aircraft aerodynamics.", "correct": false}, {"id": "c", "text": "Only financial accounting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The incident where a 737 lost oil from both engines is a direct result of.', '[{"id": "a", "text": "poor design.", "correct": false}, {"id": "b", "text": "human error.", "correct": true}, {"id": "c", "text": "engine vibration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In the cited Boeing 737 maintenance incident, loss of oil from both engines was associated with:', '[{"id": "a", "text": "An acceptable statistical probability.", "correct": false}, {"id": "b", "text": "A maintenance error affecting both engines.", "correct": true}, {"id": "c", "text": "Normal engine wear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What do you do when someone is hypothermic?.', '[{"id": "a", "text": "Warm them up.", "correct": true}, {"id": "b", "text": "Feed them sweet things because of their diabetes.", "correct": false}, {"id": "c", "text": "Give them a drink because of dehydration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Why must maintenance and inspection be included in accident prevention?', '[{"id": "a", "text": "Sophisticated aircraft eliminate maintenance risk.", "correct": false}, {"id": "b", "text": "Maintenance and inspection errors can contribute significantly to accidents.", "correct": true}, {"id": "c", "text": "Advanced maintenance practices eliminate human error.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What happened to contribute towards the incident in 1995 where a Boeing 737 lost oil pressure and had to divert?.', '[{"id": "a", "text": "Both warning indications were faulty, due to crossed connections.", "correct": false}, {"id": "b", "text": "The HP rotor drive covers of both engines had not been refitted after a boroscope inspection.", "correct": true}, {"id": "c", "text": "The boroscope inspection had been inadequate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is the most common cause of in-flight engine shutdown?.', '[{"id": "a", "text": "Incomplete installation.", "correct": true}, {"id": "b", "text": "Improper fault isolation, inspection or test.", "correct": false}, {"id": "c", "text": "Foreign object damage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Most engineering related incidents are due to.', '[{"id": "a", "text": "installing dirty connectors.", "correct": false}, {"id": "b", "text": "installing components incorrectly.", "correct": true}, {"id": "c", "text": "installing worn or old components.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which is a recognised contributor to maintenance-related incidents?', '[{"id": "a", "text": "Inadequate communication and cross-checking.", "correct": true}, {"id": "b", "text": "Correct use of approved maintenance data.", "correct": false}, {"id": "c", "text": "Effective independent inspections.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), '70 - 80% of the total focusing ability of the eye is carried out by the.', '[{"id": "a", "text": "iris.", "correct": false}, {"id": "b", "text": "cornea.", "correct": true}, {"id": "c", "text": "lens.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'At what distance should a person without hearing difficulties be able to hear an average conversational voice in a quiet room.', '[{"id": "a", "text": "2 metres (6 feet).", "correct": true}, {"id": "b", "text": "3 metres (9 feet.", "correct": false}, {"id": "c", "text": "1 metre (3 feet).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What can perforate the eardrum?', '[{"id": "a", "text": "A sufficiently intense blast or pressure change.", "correct": true}, {"id": "b", "text": "Any sound below 8 kHz.", "correct": false}, {"id": "c", "text": "Any intermittent sound above 25 kHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'How long is the short term memory good for remembering 7 items?.', '[{"id": "a", "text": "30 to 60 seconds.", "correct": false}, {"id": "b", "text": "Up to 30 seconds.", "correct": true}, {"id": "c", "text": "Above 60 seconds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is white finger?.', '[{"id": "a", "text": "A disorder of the finger which may occur through continuous use of pneumatic tools because of reduced", "correct": true}, {"id": "b", "text": "A reaction when the white blood cells die and contaminate the fingers.", "correct": false}, {"id": "c", "text": "A skin disorder caused by extensive contact with oils and solvents.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'When someone is working in an enclosed space (such a fuel tank), another person should be outside the space in constant communication to.', '[{"id": "a", "text": "provide instructions to the tradesman.", "correct": false}, {"id": "b", "text": "ensure compliance with the maintenance manual.", "correct": false}, {"id": "c", "text": "for safety reasons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The scientific study of measurements of the human body is known as.', '[{"id": "a", "text": "ergonomics.", "correct": false}, {"id": "b", "text": "physiology.", "correct": false}, {"id": "c", "text": "anthropometrics.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which statement about the acoustic reflex is correct?', '[{"id": "a", "text": "It guarantees 15 minutes of protection.", "correct": false}, {"id": "b", "text": "It gives limited protection and cannot replace hearing protection.", "correct": true}, {"id": "c", "text": "It prevents all impulse-noise injury.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What part of the eye controls the amount of light that is allowed to enter the eye?.', '[{"id": "a", "text": "The pupil.", "correct": false}, {"id": "b", "text": "The iris.", "correct": true}, {"id": "c", "text": "The cornea.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Learning of a routine by repeated practice is known as.', '[{"id": "a", "text": "cognitive learning.", "correct": false}, {"id": "b", "text": "motor programming.", "correct": true}, {"id": "c", "text": "episodic memory.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The ear is used to detect.', '[{"id": "a", "text": "speed.", "correct": false}, {"id": "b", "text": "neither acceleration or speed.", "correct": true}, {"id": "c", "text": "acceleration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Light enters the eye through the.', '[{"id": "a", "text": "cornea.", "correct": true}, {"id": "b", "text": "visual cortex.", "correct": false}, {"id": "c", "text": "retina.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'To focus on a near object, the lens of the eye must.', '[{"id": "a", "text": "be widened.", "correct": false}, {"id": "b", "text": "be flattened.", "correct": false}, {"id": "c", "text": "be thickened.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which type of memory is most susceptible to interference from external influences?.', '[{"id": "a", "text": "Long term.", "correct": false}, {"id": "b", "text": "Ultra short term.", "correct": true}, {"id": "c", "text": "Short term.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Peripheral vision is detected by the.', '[{"id": "a", "text": "cones.", "correct": false}, {"id": "b", "text": "fovea.", "correct": false}, {"id": "c", "text": "rods.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Extreme discomfort experienced by a maintenance engineer due to working in a confined space is known as.', '[{"id": "a", "text": "claustrophobia.", "correct": true}, {"id": "b", "text": "acrophobia.", "correct": false}, {"id": "c", "text": "agoraphobia.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What part of the eye is colour sensitive?.', '[{"id": "a", "text": "The rods.", "correct": false}, {"id": "b", "text": "The cones.", "correct": true}, {"id": "c", "text": "The iris.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What type of lens is used to overcome short sightedness?.', '[{"id": "a", "text": "Concave.", "correct": true}, {"id": "b", "text": "Bi-focal.", "correct": false}, {"id": "c", "text": "Convex.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The type of memory which is most easily influenced by a person''s expectations of what should have happened is the.', '[{"id": "a", "text": "long term memory.", "correct": false}, {"id": "b", "text": "semantic memory.", "correct": false}, {"id": "c", "text": "episodic memory.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The inability for the eyes to accommodate sufficiently is known as.', '[{"id": "a", "text": "Presbyopia.", "correct": true}, {"id": "b", "text": "Hypermetropia.", "correct": false}, {"id": "c", "text": "myopia.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An aircraft maintenance engineer who wears glasses or contact lenses should.', '[{"id": "a", "text": "not require their duties to be restricted providing they wear their glasses/contact lenses at all times they carry out", "correct": false}, {"id": "b", "text": "have their duties restricted accordingly.", "correct": false}, {"id": "c", "text": "not require their duties to be restricted providing they have frequent checks to ensure the adequacy of", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Ultra short term memory has a duration of about.', '[{"id": "a", "text": "10 to 20 seconds.", "correct": false}, {"id": "b", "text": "80 - 100 milliseconds.", "correct": false}, {"id": "c", "text": "2 seconds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What type of lens is used to correct long sightedness?.', '[{"id": "a", "text": "Concave.", "correct": false}, {"id": "b", "text": "Convex.", "correct": true}, {"id": "c", "text": "Bi-focal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Visual Acuity is the ability.', '[{"id": "a", "text": "to differentiate between different colours.", "correct": false}, {"id": "b", "text": "to detect objects in the peripheral vision.", "correct": false}, {"id": "c", "text": "of the eye to discriminate sharp detail at varying distances.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The ''working memory'' is.', '[{"id": "a", "text": "long term memory.", "correct": false}, {"id": "b", "text": "short term memory.", "correct": true}, {"id": "c", "text": "ultra short term memory.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Colour defective vision affects.', '[{"id": "a", "text": "almost 1 in 10 of men.", "correct": true}, {"id": "b", "text": "more women than men.", "correct": false}, {"id": "c", "text": "almost 1 in 10 of women.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'At lower light levels, the visual sensing is performed mainly by the.', '[{"id": "a", "text": "fovea.", "correct": false}, {"id": "b", "text": "cones.", "correct": false}, {"id": "c", "text": "rods.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'If an image formed on the retina of the eye is inverted relative to the viewers normal perception of the image, the viewer will.', '[{"id": "a", "text": "become disoriented and dizzy.", "correct": false}, {"id": "b", "text": "consciously mentally revert the image so as to make sense of his/her surroundings.", "correct": false}, {"id": "c", "text": "behave and feel normal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'People with colour defective vision usually have difficulty differentiating between.', '[{"id": "a", "text": "red and green.", "correct": true}, {"id": "b", "text": "blue and yellow.", "correct": false}, {"id": "c", "text": "blue and green.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The ''cocktail party effect'' is descriptive of.', '[{"id": "a", "text": "selective attention.", "correct": true}, {"id": "b", "text": "divided attention.", "correct": false}, {"id": "c", "text": "focused attention.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Hypermetropia is the medical name for.', '[{"id": "a", "text": "short sightedness.", "correct": false}, {"id": "b", "text": "long sightedness.", "correct": true}, {"id": "c", "text": "deafness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What range of sound is usually impaired first with the onset of presbycusis?.', '[{"id": "a", "text": "High pitch sound.", "correct": true}, {"id": "b", "text": "Low pitch sound.", "correct": false}, {"id": "c", "text": "Mid range sound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The amount of light which is allowed to enter the eye can vary by a factor of.', '[{"id": "a", "text": "500:1.", "correct": false}, {"id": "b", "text": "5:1.", "correct": true}, {"id": "c", "text": "1:5.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Presbyopia often effects the eyes of people after the age of.', '[{"id": "a", "text": "55.", "correct": false}, {"id": "b", "text": "40.", "correct": true}, {"id": "c", "text": "70.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'From what age does hearing ability normally begin to decline?.', '[{"id": "a", "text": "40.", "correct": false}, {"id": "b", "text": "50.", "correct": false}, {"id": "c", "text": "30.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A person with 20/40 vision has.', '[{"id": "a", "text": "worse eyesight as a person with 20/20 vision.", "correct": true}, {"id": "b", "text": "better eyesight than a person with 20/20 vision.", "correct": false}, {"id": "c", "text": "the same eyesight as a person with 20/20 vision.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Long term memory capacity is usually.', '[{"id": "a", "text": "unlimited.", "correct": true}, {"id": "b", "text": "4 - 8 years.", "correct": false}, {"id": "c", "text": "12 months.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The inability for the eyes to accommodate sufficiently is known as.', '[{"id": "a", "text": "myopia.", "correct": false}, {"id": "b", "text": "hypermetropia.", "correct": false}, {"id": "c", "text": "presbyopia.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Ultra short term memory has a duration of about.', '[{"id": "a", "text": "10 to 20 seconds.", "correct": false}, {"id": "b", "text": "2 seconds.", "correct": true}, {"id": "c", "text": "80 - 100 milliseconds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The memory can be aided by.', '[{"id": "a", "text": "a checklist.", "correct": true}, {"id": "b", "text": "memory checking.", "correct": false}, {"id": "c", "text": "mind logging.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In AWN 47 what is the recommended hearing test?.', '[{"id": "a", "text": "The ability to hear an average conversation voice at a distance of 10 feet.", "correct": false}, {"id": "b", "text": "The ability to hear a certain noise at 8 feet.", "correct": false}, {"id": "c", "text": "The ability to hear an average conversation voice at a distance of 6 feet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Iconic memory.', '[{"id": "a", "text": "stores sounds and lasts up to 2 seconds.", "correct": false}, {"id": "b", "text": "stores visual information and lasts up to 1/2 second.", "correct": true}, {"id": "c", "text": "stores visual information and lasts up to 2 seconds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The first stage in information processing is.', '[{"id": "a", "text": "decision.", "correct": false}, {"id": "b", "text": "memorizing.", "correct": false}, {"id": "c", "text": "perception.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Information, if not rehearsed is lost in.', '[{"id": "a", "text": "10 - 20 seconds.", "correct": true}, {"id": "b", "text": "1 minute.", "correct": false}, {"id": "c", "text": "30 - 40 seconds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In AWN 47, what is the standard hearing test?.', '[{"id": "a", "text": "The ability to hear a conversation in a quiet room at 2 metres.", "correct": true}, {"id": "b", "text": "The ability to hear a conversation in a quiet room at 10 metres.", "correct": false}, {"id": "c", "text": "The ability to hear a conversation in a noisy room at 2 metres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Information in the short term memory not rehearsed will be lost in.', '[{"id": "a", "text": "10 - 20 seconds.", "correct": true}, {"id": "b", "text": "1 - 3 months.", "correct": false}, {"id": "c", "text": "2 - 3 weeks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which general statement about visual capability is appropriate for maintenance work?', '[{"id": "a", "text": "Only uncorrected vision is acceptable.", "correct": false}, {"id": "b", "text": "Vision, with suitable correction if needed, must be adequate for the assigned task.", "correct": true}, {"id": "c", "text": "A single 18/20 threshold covers every task.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which eye structure supplies most of the refractive power?', '[{"id": "a", "text": "Iris.", "correct": false}, {"id": "b", "text": "Lens.", "correct": false}, {"id": "c", "text": "Cornea.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The average capacity of the working memory is about.', '[{"id": "a", "text": "7 chunks of information.", "correct": true}, {"id": "b", "text": "4 chunks of information.", "correct": false}, {"id": "c", "text": "12 chunks of information.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The retina is situated.', '[{"id": "a", "text": "behind the cornea with the lens.", "correct": false}, {"id": "b", "text": "in front of the cornea.", "correct": false}, {"id": "c", "text": "at the back of the eye with the optic nerve.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Motor programme refers to.', '[{"id": "a", "text": "motivational computer software.", "correct": false}, {"id": "b", "text": "a task that has been carried out so many times that it becomes automatic.", "correct": true}, {"id": "c", "text": "a task that becomes programmed into short term memory.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Memory which can be influenced by a persons expectations of what should have happened is.', '[{"id": "a", "text": "echoic.", "correct": false}, {"id": "b", "text": "semantic.", "correct": false}, {"id": "c", "text": "episodic.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which statement about long-term memory is correct?', '[{"id": "a", "text": "Information can be retrieved into working memory, although retrieval is not always easy.", "correct": true}, {"id": "b", "text": "Information is normally lost immediately.", "correct": false}, {"id": "c", "text": "Information is accessible only under hypnosis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is the traditional training-model capacity of short-term memory?', '[{"id": "a", "text": "About 5 to 9 chunks.", "correct": true}, {"id": "b", "text": "9 to 15 unrelated items as a general rule.", "correct": false}, {"id": "c", "text": "Unlimited.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In the eye, the cones are used mainly in.', '[{"id": "a", "text": "bright light to give fine detail.", "correct": true}, {"id": "b", "text": "bright light levels and they give poor colour vision.", "correct": false}, {"id": "c", "text": "low light levels and they give poor colour vision.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A person suffering from presbyopia would normally.', '[{"id": "a", "text": "wear spectacles when reading or carrying out close detail work.", "correct": true}, {"id": "b", "text": "have defective colour vision and not be allowed to carry out maintenance work on cable looms.", "correct": false}, {"id": "c", "text": "be short sighted and need to wear spectacles to see objects more than 30 cm away.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Noise signals are carried to the brain by the.', '[{"id": "a", "text": "sensory nerve.", "correct": false}, {"id": "b", "text": "auditory nerve.", "correct": true}, {"id": "c", "text": "Eustachian nerve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Poking sharp objects into the ear should be avoided as it is likely to result in.', '[{"id": "a", "text": "tinnitus ringing.", "correct": false}, {"id": "b", "text": "conductive hearing loss.", "correct": false}, {"id": "c", "text": "tympanic membrane perforation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Attention Getters are designed to.', '[{"id": "a", "text": "to gain the operators attention whilst allowing them to continue with the task in hand.", "correct": false}, {"id": "b", "text": "to make the operator focus his/her attention fully on the task in hand.", "correct": false}, {"id": "c", "text": "to get the operators full attention.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'At what maximum frequency does the human ear hear?.', '[{"id": "a", "text": "16 kHz.", "correct": false}, {"id": "b", "text": "8 kHz.", "correct": false}, {"id": "c", "text": "20 kHz.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What are motor programmes?', '[{"id": "a", "text": "Learned sequences of actions that can run with little conscious attention.", "correct": true}, {"id": "b", "text": "Actions that always require deliberate step-by-step thought.", "correct": false}, {"id": "c", "text": "Temporary sensory traces only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The pupil of the eye grows smaller.', '[{"id": "a", "text": "in condition of reduced light.", "correct": false}, {"id": "b", "text": "to focus the fovea.", "correct": false}, {"id": "c", "text": "in condition of increased light.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Conductive hearing loss may result from damage to the:', '[{"id": "a", "text": "Eardrum or middle-ear ossicles.", "correct": true}, {"id": "b", "text": "Cochlear sensory cells only.", "correct": false}, {"id": "c", "text": "Semicircular canals only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Detail is best sensed by the ______ and movement best sensed by the ______.', '[{"id": "a", "text": "the periphery and the periphery.", "correct": false}, {"id": "b", "text": "the periphery and fovea.", "correct": false}, {"id": "c", "text": "the fovea and periphery.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'If a person is colour blind, which colours would be most difficult to see?.', '[{"id": "a", "text": "Red and green.", "correct": true}, {"id": "b", "text": "Blue and red.", "correct": false}, {"id": "c", "text": "Yellow and red.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Myopia is _______ and a ______ lens is needed to correct it.', '[{"id": "a", "text": "long sightedness and concave.", "correct": false}, {"id": "b", "text": "short sightedness and convex.", "correct": false}, {"id": "c", "text": "short sightedness and concave.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The Otoliths detect.', '[{"id": "a", "text": "angular acceleration.", "correct": false}, {"id": "b", "text": "linear acceleration.", "correct": true}, {"id": "c", "text": "both angular and linear acceleration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which functions does the nose perform on inhaled air?', '[{"id": "a", "text": "Filtering only.", "correct": false}, {"id": "b", "text": "Filtering, warming and humidifying.", "correct": true}, {"id": "c", "text": "Producing oxygen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The most common cause of myopia is.', '[{"id": "a", "text": "weak accommodation.", "correct": false}, {"id": "b", "text": "a shortened eyeball.", "correct": false}, {"id": "c", "text": "an elongated eyeball.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is peer group pressure?.', '[{"id": "a", "text": "The influence the House of Lords have over the House of Commons.", "correct": false}, {"id": "b", "text": "Our behaviour influenced by our friends and colleagues.", "correct": true}, {"id": "c", "text": "The influence an individual has over a group of people.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A regular behaviour of an individual is known as.', '[{"id": "a", "text": "the norm.", "correct": false}, {"id": "b", "text": "habit.", "correct": true}, {"id": "c", "text": "culture.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In a discussion, the person who is most likely to be agreed with is.', '[{"id": "a", "text": "the person who repeats the point most times.", "correct": false}, {"id": "b", "text": "the most argumentative person.", "correct": false}, {"id": "c", "text": "the person with the highest status.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An engineer who has developed his own way of performing a task.', '[{"id": "a", "text": "is in regular violation.", "correct": true}, {"id": "b", "text": "is improving maintenance efficiency.", "correct": false}, {"id": "c", "text": "should be commended for his resourcefulness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The aim of human factors programs within an organizations is.', '[{"id": "a", "text": "to safeguard the health and safety of maintenance personnel by reducing accidents in the workplace.", "correct": false}, {"id": "b", "text": "to optimize the relationship between maintenance personnel and systems with a view to improving safety,", "correct": true}, {"id": "c", "text": "to reduce costs by increasing efficiency, safety and quality and decreasing waste through human error.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An aircraft engineer who has ''responsibility''.', '[{"id": "a", "text": "must be licensed on the particular type of aircraft.", "correct": false}, {"id": "b", "text": "are liable to be called to account as being in charge or control of, or answerable for something.", "correct": true}, {"id": "c", "text": "is in a management position within their company hierarchy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The impact of human factors and human error is most important to.', '[{"id": "a", "text": "technicians and engineers.", "correct": false}, {"id": "b", "text": "planners and managers.", "correct": false}, {"id": "c", "text": "It is equally important to technicians, engineers, planners and managers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Where should an engineer check the responsibilities attached to a maintenance authorisation?', '[{"id": "a", "text": "The applicable regulations and the organisation''s approved procedures and authorisation.", "correct": true}, {"id": "b", "text": "Only an old study question bank.", "correct": false}, {"id": "c", "text": "Only informal advice from colleagues.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Diffusion of responsibility may occur.', '[{"id": "a", "text": "to an individual working as a member of a team.", "correct": true}, {"id": "b", "text": "with certain people whether they are working in a team or alone.", "correct": false}, {"id": "c", "text": "to an individual working alone.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Risky shift'' is.', '[{"id": "a", "text": "the probability of being assigned to a work task which involves some element of risk or physical danger.", "correct": false}, {"id": "b", "text": "the name given to an inadequate shift handover.", "correct": false}, {"id": "c", "text": "the tendency for a group of workers to arrive at a course of action which is riskier than that which any", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'To ensure that a technician remains reasonably current on the aircraft types to which they hold authorizations, they are required that.', '[{"id": "a", "text": "they have appropriate continuation/refresher training only.", "correct": false}, {"id": "b", "text": "they are involved in at least 6 months of actual aircraft maintenance experience in any 2 year period only.", "correct": false}, {"id": "c", "text": "they are involved in at least 6 months of actual aircraft maintenance experience in any 2 year period and", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The difference between what a person ''can'' do and what he ''will'' do is largely determined by his.', '[{"id": "a", "text": "motivation.", "correct": true}, {"id": "b", "text": "education and training.", "correct": false}, {"id": "c", "text": "physical and mental health.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Whose responsibility is it that an engineer remains current on new technology and procedures?.', '[{"id": "a", "text": "The organization''s.", "correct": false}, {"id": "b", "text": "The CAA''s.", "correct": false}, {"id": "c", "text": "The engineer''s.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'According to Maslow, safety needs (protection from potentially dangerous objects or situations).', '[{"id": "a", "text": "is the last need of human after all other needs have been satisfied.", "correct": false}, {"id": "b", "text": "is second only to physiological needs (food drink, oxygen etc.).", "correct": true}, {"id": "c", "text": "is the most primal need of humans.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The symptoms of de-motivation are very similar to the symptoms of.', '[{"id": "a", "text": "stress.", "correct": true}, {"id": "b", "text": "tiredness.", "correct": false}, {"id": "c", "text": "mental illness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The desire of an individual to ''conform'' to a group by allowing one''s opinions, attitudes and actions to be affected by prevailing conditions is known as.', '[{"id": "a", "text": "peer pressure.", "correct": true}, {"id": "b", "text": "esteem needs.", "correct": false}, {"id": "c", "text": "culture issues.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Confirmation bias'' is.', '[{"id": "a", "text": "error in work carried out by a supervisor who has also inspected and signed for his own work.", "correct": false}, {"id": "b", "text": "an inspection of work carried out by an independent inspector or supervisor.", "correct": false}, {"id": "c", "text": "the subconscious attention to evidence which confirms an engineer''s beliefs, and inattention to evidence", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A person with low self-esteem is.', '[{"id": "a", "text": "more likely to conform to peer pressure.", "correct": true}, {"id": "b", "text": "less likely to conform to peer pressure.", "correct": false}, {"id": "c", "text": "Conformity to peer pressure is not affected by level of self-esteem.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Motivation is.', '[{"id": "a", "text": "a reward or punishment designed to reduce errors.", "correct": false}, {"id": "b", "text": "a reward or punishment designed to increase work rate.", "correct": false}, {"id": "c", "text": "the thing that drives someone to do something.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Peer pressure is', '[{"id": "a", "text": "the perceived pressure to carry out a task in the same way your colleagues would.", "correct": false}, {"id": "b", "text": "the perceived pressure to conform to what you believe your colleagues expect of you.", "correct": true}, {"id": "c", "text": "Nothing", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The eyesight of an engineer is the responsibility of.', '[{"id": "a", "text": "the Quality Manager.", "correct": false}, {"id": "b", "text": "the optician.", "correct": false}, {"id": "c", "text": "the engineer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A good team is one where every member has.', '[{"id": "a", "text": "an opinion.", "correct": false}, {"id": "b", "text": "an input.", "correct": true}, {"id": "c", "text": "a job.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'AWN 47 states that the engineer.', '[{"id": "a", "text": "is responsible for health and safety.", "correct": false}, {"id": "b", "text": "is responsible for the work he has signed for.", "correct": false}, {"id": "c", "text": "does not report for work if unfit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An effective group work is when.', '[{"id": "a", "text": "everyone contributes in some way.", "correct": true}, {"id": "b", "text": "everyone discusses ideas and opinions.", "correct": false}, {"id": "c", "text": "everyone has a job to do.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which of the following defines a peer pressure situation?.', '[{"id": "a", "text": "Your supervising manager pressuring you to complete the current task on time.", "correct": false}, {"id": "b", "text": "Your girlfriend telling you to go out with her.", "correct": false}, {"id": "c", "text": "Your colleagues pressuring you to work faster so they can go home.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Successful working teams have the following attributes:-.', '[{"id": "a", "text": "Members participate in team activities but retain their own individual requirements.", "correct": false}, {"id": "b", "text": "All the members participate in team activities and discussions.", "correct": true}, {"id": "c", "text": "All the team members work in isolation and therefore provide highly individual solutions to the same problems.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Good aircraft maintenance supervisory judgment is usually based upon.', '[{"id": "a", "text": "knowledge and experience and reference to approved data.", "correct": true}, {"id": "b", "text": "the evidence available and forceful management ability.", "correct": false}, {"id": "c", "text": "knowledge and experience and reference to course notes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Organizational culture (whether good or bad) is best described as.', '[{"id": "a", "text": "the way we do things around here''.", "correct": true}, {"id": "b", "text": "written procedures.", "correct": false}, {"id": "c", "text": "team resource management.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What best describes a just culture?', '[{"id": "a", "text": "Punish every error.", "correct": false}, {"id": "b", "text": "Encourage reporting and learning while distinguishing acceptable mistakes from unacceptable behaviour.", "correct": true}, {"id": "c", "text": "Remove all accountability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A person can be said to be motivated if.', '[{"id": "a", "text": "they cut corners to get the job done quickly.", "correct": false}, {"id": "b", "text": "they are on a productivity bonus.", "correct": false}, {"id": "c", "text": "they are taking action to achieve something.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Group polarisation can result in.', '[{"id": "a", "text": "a group making a more cautious or extreme decision.", "correct": true}, {"id": "b", "text": "a group making a better decision than the individual.", "correct": false}, {"id": "c", "text": "members of the group not talking to one another.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which behaviour increases the risk of deviating from standard procedures?', '[{"id": "a", "text": "Overconfidence and a belief that procedures are unnecessary.", "correct": true}, {"id": "b", "text": "Checking current approved data.", "correct": false}, {"id": "c", "text": "Seeking clarification when unsure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The ideal behaviour of a professional aircraft engineer is.', '[{"id": "a", "text": "goal directed rather than person directed.", "correct": false}, {"id": "b", "text": "both person and goal directed.", "correct": true}, {"id": "c", "text": "neither person or goal directed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Information on drugs and alcohol can be found in.', '[{"id": "a", "text": "BCARs.", "correct": false}, {"id": "b", "text": "AWN 47.", "correct": true}, {"id": "c", "text": "AWN 3.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Before undertaking safety-critical work while starting a new medicine, you should:', '[{"id": "a", "text": "Assume all prescribed medicines are safe for duty.", "correct": false}, {"id": "b", "text": "Obtain appropriate medical or occupational advice and assess effects before duty.", "correct": true}, {"id": "c", "text": "Use a fixed 24-hour trial as a guarantee of fitness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'After a general anaesthetic you should.', '[{"id": "a", "text": "return to work as soon as possible.", "correct": false}, {"id": "b", "text": "not return to work for at least 24 to 48 hours (depending on the individual).", "correct": true}, {"id": "c", "text": "take at least 7 days off work.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'If prescribed a sedating medicine, what should an aircraft engineer do?', '[{"id": "a", "text": "Conceal it and continue duty.", "correct": false}, {"id": "b", "text": "Obtain fitness-for-duty advice and avoid safety-critical work while impaired.", "correct": true}, {"id": "c", "text": "Assume all non-safety-critical employment is permanently prohibited.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which statement about stimulant use is appropriate?', '[{"id": "a", "text": "Stimulants replace sleep.", "correct": false}, {"id": "b", "text": "Unsupervised stimulant pills are a suitable fatigue countermeasure.", "correct": false}, {"id": "c", "text": "Do not use stimulant drugs to override fatigue; use rest and approved fatigue controls.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Before using a decongestant while performing safety-critical maintenance, you should:', '[{"id": "a", "text": "Assume a brand name guarantees no side effects.", "correct": false}, {"id": "b", "text": "Assess the actual ingredients, illness and effects with appropriate medical advice.", "correct": true}, {"id": "c", "text": "Ignore the illness if symptoms are masked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In modern sleep staging, slow-wave sleep is:', '[{"id": "a", "text": "REM sleep.", "correct": false}, {"id": "b", "text": "N3 deep non-REM sleep.", "correct": true}, {"id": "c", "text": "All of N1 and N2 only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Phase 3/4 sleep.', '[{"id": "a", "text": "can be induced by alcohol.", "correct": false}, {"id": "b", "text": "occurs only once per sleep cycle.", "correct": false}, {"id": "c", "text": "is most beneficial for the body''s restoration.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which thermal conditions can impair human performance?', '[{"id": "a", "text": "Only unusually high temperature.", "correct": false}, {"id": "b", "text": "Both excessive heat and excessive cold.", "correct": true}, {"id": "c", "text": "Only unusually low temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is sensible nutrition after a long shift?', '[{"id": "a", "text": "A balanced meal appropriate to needs, with hydration.", "correct": true}, {"id": "b", "text": "Only sugar.", "correct": false}, {"id": "c", "text": "Only protein, regardless of needs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is a likely consequence of excessively long shifts?', '[{"id": "a", "text": "Permanent improvement with no fatigue risk.", "correct": false}, {"id": "b", "text": "Increased fatigue and reduced diagnostic performance.", "correct": true}, {"id": "c", "text": "Guaranteed improvement in defect detection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The circadian cycle body temperature.', '[{"id": "a", "text": "does not vary.", "correct": false}, {"id": "b", "text": "varies by 1.5°C.", "correct": false}, {"id": "c", "text": "varies by 1.5°F.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Acute stress is.', '[{"id": "a", "text": "intense stress of long duration.", "correct": false}, {"id": "b", "text": "typically intense but of short duration.", "correct": true}, {"id": "c", "text": "a frequently reoccurring stress or of long duration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Chronic stress is.', '[{"id": "a", "text": "a frequently reoccurring stress or of long duration.", "correct": true}, {"id": "b", "text": "typically intense but of short duration.", "correct": false}, {"id": "c", "text": "intense stress of long duration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Smoking cannabis.', '[{"id": "a", "text": "subtly impairs performance for up to 24 hours.", "correct": true}, {"id": "b", "text": "has only a short term affect upon performance.", "correct": false}, {"id": "c", "text": "has a noticeable affect on a persons behaviour and performance for up to 24 hours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Performance is.', '[{"id": "a", "text": "inversely proportional to the individuals state of arousal.", "correct": false}, {"id": "b", "text": "directly proportional to the individuals state of arousal.", "correct": false}, {"id": "c", "text": "greatest only at one optimum level of arousal but diminishes as arousal decreases or increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Missing a break in an effort to get a job done within a certain time frame.', '[{"id": "a", "text": "can be done by those actually doing the job providing the supervisors take regular breaks.", "correct": false}, {"id": "b", "text": "can be counterproductive, as fatigue diminishes motor skills, perception, awareness and standards.", "correct": true}, {"id": "c", "text": "can be done providing adequate rest period is available at the end of the shift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Tiredness causes visual acuity to.', '[{"id": "a", "text": "decrease.", "correct": true}, {"id": "b", "text": "Visual acuity is not affected by tiredness.", "correct": false}, {"id": "c", "text": "increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Narrowing of attention occurs at.', '[{"id": "a", "text": "low levels of arousal.", "correct": false}, {"id": "b", "text": "both high and low levels of arousal.", "correct": false}, {"id": "c", "text": "high levels of arousal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which rule should guide alcohol and safety-critical maintenance?', '[{"id": "a", "text": "A road-driving limit automatically establishes fitness.", "correct": false}, {"id": "b", "text": "Remain fit for duty and comply with the applicable aviation law and employer policy.", "correct": true}, {"id": "c", "text": "A fixed blood-alcohol number applies identically worldwide.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Paradoxical sleep is also known as.', '[{"id": "a", "text": "Stage 3 sleep.", "correct": false}, {"id": "b", "text": "Stage 4 sleep.", "correct": false}, {"id": "c", "text": "REM sleep.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'When starting a medicine before maintenance duties, what should you do?', '[{"id": "a", "text": "Seek appropriate fitness-for-duty advice and establish that neither illness nor medicine impairs safe", "correct": true}, {"id": "b", "text": "Assume 24 hours always removes all risk.", "correct": false}, {"id": "c", "text": "Rely solely on whether it was prescribed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What should be done with the old 28-units-per-week health recommendation in this bank?', '[{"id": "a", "text": "Treat it as current universal advice.", "correct": false}, {"id": "b", "text": "Recognise it as outdated and consult current national health guidance.", "correct": true}, {"id": "c", "text": "Interpret it as 28 units per day.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Human Circadian rhythms cycle on a.', '[{"id": "a", "text": "25 hour timescale.", "correct": false}, {"id": "b", "text": "8 hour timescale.", "correct": false}, {"id": "c", "text": "24 hour time scale.", "correct": true}]'::jsonb, '{B1,B2}'),
