    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Long shift work will.', '[{"id": "a", "text": "increase your diagnostic and maintenance ability.", "correct": false}, {"id": "b", "text": "initially decrease your diagnostic and maintenance ability but then you will get used to it.", "correct": true}, {"id": "c", "text": "decrease your diagnostic and maintenance ability.", "correct": false}]'::jsonb, '{B1,B2}'),
