    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which statement about manual lifting is correct?', '[{"id": "a", "text": "23 kg is a universal safe limit.", "correct": false}, {"id": "b", "text": "Safe handling depends on the load, posture, reach, frequency, environment and person.", "correct": true}, {"id": "c", "text": "Anything below 50 kg is always safe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Sensing and perception errors are most likely to result from.', '[{"id": "a", "text": "distraction of other engineers.", "correct": false}, {"id": "b", "text": "poor lighting or noise.", "correct": true}, {"id": "c", "text": "lack of adequate training.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Task lighting in a hangar is mainly.', '[{"id": "a", "text": "provided by fixed lighting.", "correct": false}, {"id": "b", "text": "provided by fluorescent tubes.", "correct": false}, {"id": "c", "text": "portable so that individual tasks may be well lit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'When inspecting an airframe structure for small cracks, to avoid a crack being missed you should.', '[{"id": "a", "text": "hold the vision stationary for several seconds on each area to allow the eye to focus correctly.", "correct": false}, {"id": "b", "text": "not use a mirror as mirrors absorb and refract light and may obscure a crack.", "correct": false}, {"id": "c", "text": "constantly move the eye across and around the area of interest to avoid the crack falling into the eye''s", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What happens when moving from a dark area to a brightly lit area?', '[{"id": "a", "text": "Light adaptation is generally faster than full dark adaptation; allow vision to settle for the task.", "correct": true}, {"id": "b", "text": "A universal minimum of seven minutes always applies.", "correct": false}, {"id": "c", "text": "No adaptation takes place.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Itemized checklists should be dealt with.', '[{"id": "a", "text": "in any order, provided all steps are completed.", "correct": false}, {"id": "b", "text": "item by item, in order, to cover every step diligently.", "correct": true}, {"id": "c", "text": "as memorized.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The main disadvantage of carrying out critical inspections under very bright artificial light is.', '[{"id": "a", "text": "glare.", "correct": true}, {"id": "b", "text": "shadows.", "correct": false}, {"id": "c", "text": "filtered light.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'When carrying out a visual inspection, an engineer is likely to make a parallax error when.', '[{"id": "a", "text": "inspecting a component using a 5x or 10x magnifying glass.", "correct": false}, {"id": "b", "text": "using precision measuring instruments such as a vernier gauge or AVO meter.", "correct": true}, {"id": "c", "text": "Nothing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What constitutes a good work handover?.', '[{"id": "a", "text": "A written and verbal account of the work done.", "correct": true}, {"id": "b", "text": "A written documentation of the work done.", "correct": false}, {"id": "c", "text": "A verbal account of the work done.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A good shift handover should include details of.', '[{"id": "a", "text": "tasks that have been completed; persons who carried out the tasks; tasks to be carried out and general company", "correct": false}, {"id": "b", "text": "tasks that have been completed; tasks in progress, their status, any problems encountered etc.; tasks to be carried", "correct": false}, {"id": "c", "text": "tasks that have been completed; tasks in progress, their status, any problems encountered etc.; tasks to", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A good practice for a shift handover is for shifts to be specifically rostered so there is an overlap of.', '[{"id": "a", "text": "2 - 3 hours.", "correct": false}, {"id": "b", "text": "5 - 10 minutes.", "correct": false}, {"id": "c", "text": "20 - 30 minutes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Asynchronous'' communication includes.', '[{"id": "a", "text": "immediate voice communication by radio link.", "correct": false}, {"id": "b", "text": "technical manuals, memos, Advisory Circulars and Airworthiness Directives.", "correct": true}, {"id": "c", "text": "face-to-face communications.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The most effective form of communication is.', '[{"id": "a", "text": "verbal communication.", "correct": false}, {"id": "b", "text": "written communication.", "correct": false}, {"id": "c", "text": "explicit communication.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is the most important means of communication in aircraft maintenance engineering?.', '[{"id": "a", "text": "Written.", "correct": true}, {"id": "b", "text": "Implicit.", "correct": false}, {"id": "c", "text": "Verbal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'If you are given a task that you are unsure of you should.', '[{"id": "a", "text": "consult the appropriate approved data.", "correct": true}, {"id": "b", "text": "ask someone who has done it before.", "correct": false}, {"id": "c", "text": "consult type course notes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'How should an important failure warning be presented?', '[{"id": "a", "text": "With an appropriate conspicuous combination of cues matched to urgency and system design.", "correct": true}, {"id": "b", "text": "Always by sound alone.", "correct": false}, {"id": "c", "text": "Always by a dolls-eye indicator alone.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The SHEL model of human factors takes into account.', '[{"id": "a", "text": "Software, hardware, environment and liveware.", "correct": true}, {"id": "b", "text": "Software, hardware, efficiency and liveware.", "correct": false}, {"id": "c", "text": "Software, hardware, environment and location.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What part of the SHEL model would the writing and interpretation of maintenance manuals fit into?.', '[{"id": "a", "text": "Hardware.", "correct": false}, {"id": "b", "text": "Software.", "correct": true}, {"id": "c", "text": "Environment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The ''error chain'' theory refers to.', '[{"id": "a", "text": "a chain of errors within an organizations can be investigated, and similar errors prevented by determining a", "correct": false}, {"id": "b", "text": "a company is only as good as its weakest employee or employees, and removal of that/those employee from the", "correct": false}, {"id": "c", "text": "errors are caused by a chain of linked events, and the breaking of one link in the chain will prevent the", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What part of the SHEL model would the aircraft design fit into?.', '[{"id": "a", "text": "Liveware.", "correct": false}, {"id": "b", "text": "Hardware.", "correct": true}, {"id": "c", "text": "Environment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which part of the SHEL model is most difficult to protect from errors by ''designing out'' or to ''work around''?.', '[{"id": "a", "text": "Liveware.", "correct": true}, {"id": "b", "text": "Software.", "correct": false}, {"id": "c", "text": "Environment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A violation in an aircraft maintenance procedure.', '[{"id": "a", "text": "is usually carried out with the best intentions from a genuine desire to ''get the job done''.", "correct": true}, {"id": "b", "text": "is always considered an act of vandalism or sabotage.", "correct": false}, {"id": "c", "text": "is always carried out to satisfy some personal need, often unrelated to the actual task.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which type of human error is easiest to correct?.', '[{"id": "a", "text": "Constant error.", "correct": true}, {"id": "b", "text": "Reversible error.", "correct": false}, {"id": "c", "text": "Variable error.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In the ''slips, lapses and mistakes'' definition of errors, forgetting to replace an engine cowling would be considered a.', '[{"id": "a", "text": "mistake.", "correct": false}, {"id": "b", "text": "lapse.", "correct": true}, {"id": "c", "text": "slip.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'In the ''slips, lapses and mistakes'' definition of errors, a mistake would typically occur at the.', '[{"id": "a", "text": "storage (memory) stage.", "correct": false}, {"id": "b", "text": "execution stage.", "correct": false}, {"id": "c", "text": "planning stage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'On a task that is complex, an engineer uses his own procedures due to pressure. This is legally termed.', '[{"id": "a", "text": "modification.", "correct": false}, {"id": "b", "text": "initiative.", "correct": false}, {"id": "c", "text": "violation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Visual inspection by an ''experienced'' maintenance engineer is.', '[{"id": "a", "text": "knowledge and rule base behaviour.", "correct": true}, {"id": "b", "text": "skill and knowledge based behaviour.", "correct": false}, {"id": "c", "text": "skill and rule based behaviour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Troubleshooting using a known fault-isolation procedure is mainly:', '[{"id": "a", "text": "Rule-based behaviour.", "correct": true}, {"id": "b", "text": "An automatic motor action only.", "correct": false}, {"id": "c", "text": "Always novel knowledge-based reasoning.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A violation is.', '[{"id": "a", "text": "an unintentional error.", "correct": false}, {"id": "b", "text": "a deliberate departure from the rules.", "correct": true}, {"id": "c", "text": "an intentional act of sabotage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A mistake is.', '[{"id": "a", "text": "a deliberate departure from the rules.", "correct": false}, {"id": "b", "text": "an intentional act of sabotage.", "correct": false}, {"id": "c", "text": "an unintentional error.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Whilst working on an aircraft a spanner placed on the wing surface is kicked off and subsequently falls into an open engine cowl, breaking off a sensor connector. This is an example of.', '[{"id": "a", "text": "a skill based error.", "correct": true}, {"id": "b", "text": "Murphy''s law.", "correct": false}, {"id": "c", "text": "a punishable occurrence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An engineer knows which seal is required but accidentally picks a different one during a familiar task. This is mainly:', '[{"id": "a", "text": "A skill-based slip.", "correct": true}, {"id": "b", "text": "A deliberate violation.", "correct": false}, {"id": "c", "text": "A knowledge-based mistake.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An engineer is working on a wing and kicks a spanner off into an engine cowl and breaks a sensor. This is.', '[{"id": "a", "text": "knowledge based error.", "correct": false}, {"id": "b", "text": "skill based error.", "correct": true}, {"id": "c", "text": "rule based error.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The difference between a mistake and a violation is.', '[{"id": "a", "text": "a mistake is less serious than a violation.", "correct": false}, {"id": "b", "text": "a violation is not deliberate.", "correct": false}, {"id": "c", "text": "a mistake is unintentional and a violation is deliberate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An engineer intends to follow the procedure but forgets a required seal. This is:', '[{"id": "a", "text": "A knowledge-based planning mistake.", "correct": false}, {"id": "b", "text": "A deliberate violation.", "correct": false}, {"id": "c", "text": "A memory lapse during task execution.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'The hub of the SHEL model of human factors is.', '[{"id": "a", "text": "liveware.", "correct": true}, {"id": "b", "text": "hardware.", "correct": false}, {"id": "c", "text": "enviroment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'A type 1 visual inspection error occurs when.', '[{"id": "a", "text": "a faulty item is missed.", "correct": false}, {"id": "b", "text": "a good item is incorrectly identified as faulty.", "correct": true}, {"id": "c", "text": "a duplicate inspection is not carried out.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is the difference between error and violation?.', '[{"id": "a", "text": "Violation is deliberate, error is not.", "correct": true}, {"id": "b", "text": "Error is deliberate, violation is not.", "correct": false}, {"id": "c", "text": "No difference.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is a latent condition?', '[{"id": "a", "text": "An underlying weakness that may remain dormant until combined with other failures.", "correct": true}, {"id": "b", "text": "Every immediately visible front-line error.", "correct": false}, {"id": "c", "text": "Only an unpredictable mechanical failure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What happens when you break the ''chain of error''?.', '[{"id": "a", "text": "Accident happens.", "correct": false}, {"id": "b", "text": "Pilot submits report within 72 hours.", "correct": false}, {"id": "c", "text": "Accident does not happen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'If an engineer forgets to fit a seal to an engine drain plug, he or she has.', '[{"id": "a", "text": "made an error of commission.", "correct": false}, {"id": "b", "text": "committed a violation.", "correct": false}, {"id": "c", "text": "made an error of omission.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An engineer knowingly departs from a required procedure because current conditions make compliance difficult. This is most consistent with:', '[{"id": "a", "text": "A routine slip.", "correct": false}, {"id": "b", "text": "A situational violation.", "correct": true}, {"id": "c", "text": "An involuntary memory lapse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'An engineer who has developed his or her own method of performing a complex task.', '[{"id": "a", "text": "should be commended for his/her resourcefulness.", "correct": false}, {"id": "b", "text": "is performing a rule based behaviour.", "correct": false}, {"id": "c", "text": "is violating on a regular basis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Error tolerance in maintenance progress refers to.', '[{"id": "a", "text": "performance of tasks specifically designed to identify errors during a maintenance task.", "correct": false}, {"id": "b", "text": "ability of a system to remain functional after a maintenance error.", "correct": true}, {"id": "c", "text": "process of eliminating the contributing factors to error.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Engineers often work on raised platforms, ladders etc. What dangers can this contribute to?.', '[{"id": "a", "text": "Staging may be made of wood.", "correct": false}, {"id": "b", "text": "Ladder may slip and man falls.", "correct": true}, {"id": "c", "text": "Two workers may be carrying out maintenance on the same lift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Risk assessment and management is.', '[{"id": "a", "text": "reduction of risks to a tolerable standard and monitoring the situation.", "correct": true}, {"id": "b", "text": "the investigation of risks and totally removing them and the monitoring of new work practices.", "correct": false}, {"id": "c", "text": "choosing a cheaper supplier or manufacturer for parts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'When carrying out a risk assessment.', '[{"id": "a", "text": "a hard hat should be worn.", "correct": false}, {"id": "b", "text": "it is necessary to identify where equipment/procedures might fail.", "correct": true}, {"id": "c", "text": "Nothing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which is a dynamic display?', '[{"id": "a", "text": "Altimeter.", "correct": true}, {"id": "b", "text": "Static sign chart.", "correct": false}, {"id": "c", "text": "Placard.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is measurement of human body dimensions called?', '[{"id": "a", "text": "Biomechanics.", "correct": false}, {"id": "b", "text": "Anthropometry.", "correct": true}, {"id": "c", "text": "Kinesiology.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'How can uncritical reliance on a familiar subconscious interpretation affect awareness?', '[{"id": "a", "text": "It always increases awareness.", "correct": false}, {"id": "b", "text": "It can reduce awareness of changed conditions.", "correct": true}, {"id": "c", "text": "It guarantees correct decisions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which approach should guide human-centred aviation job design?', '[{"id": "a", "text": "Consider only practical experience.", "correct": false}, {"id": "b", "text": "Consider only past habits.", "correct": false}, {"id": "c", "text": "Fit tasks to human capabilities, limitations and motivation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is a sound basis for a risk-management decision?', '[{"id": "a", "text": "Identify hazards, assess risk, choose controls and review their effectiveness.", "correct": true}, {"id": "b", "text": "Only managers can recognise risk.", "correct": false}, {"id": "c", "text": "No structured process exists.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Health, diet, fitness and alcohol use can affect which aspects of performance?', '[{"id": "a", "text": "Physical aspects only.", "correct": false}, {"id": "b", "text": "Psychological aspects only.", "correct": false}, {"id": "c", "text": "Both physical and psychological aspects.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What should an optimum visual working environment consider?', '[{"id": "a", "text": "The visibility of the task only.", "correct": false}, {"id": "b", "text": "Absence of light.", "correct": false}, {"id": "c", "text": "Both task visibility and the capabilities and limitations of the eyes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'How can active failures and latent conditions contribute to an accident?', '[{"id": "a", "text": "They can combine to defeat the layers of defence.", "correct": true}, {"id": "b", "text": "They always independently cause an accident.", "correct": false}, {"id": "c", "text": "They cannot affect defences.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What constitutes a good shift handover?', '[{"id": "a", "text": "Written information only.", "correct": false}, {"id": "b", "text": "Verbal information only.", "correct": false}, {"id": "c", "text": "Written records supported by verbal communication.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What is a violation?', '[{"id": "a", "text": "An unintentional action error.", "correct": false}, {"id": "b", "text": "A deliberate departure from a rule or procedure.", "correct": true}, {"id": "c", "text": "Always sabotage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What should an ergonomic workplace audit consider?', '[{"id": "a", "text": "Workbenches and chairs only.", "correct": false}, {"id": "b", "text": "Tools and test equipment only.", "correct": false}, {"id": "c", "text": "Workstations, tools, equipment and the working environment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Who should task analysis represent?', '[{"id": "a", "text": "Only the designer.", "correct": false}, {"id": "b", "text": "Only management.", "correct": false}, {"id": "c", "text": "The actual people who perform or will use the task or system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'Which can contribute to a maintenance-related accident?', '[{"id": "a", "text": "Design deficiencies.", "correct": false}, {"id": "b", "text": "Communication failures.", "correct": false}, {"id": "c", "text": "Design, communication and procedural deficiencies.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'How can personal stress affect performance?', '[{"id": "a", "text": "It always improves concentration.", "correct": false}, {"id": "b", "text": "It has no effect on sleep.", "correct": false}, {"id": "c", "text": "It can reduce concentration and disrupt sleep or cause fatigue.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What can an organisation provide to support employee performance?', '[{"id": "a", "text": "Bed sheets as the principal control.", "correct": false}, {"id": "b", "text": "Diet alone.", "correct": false}, {"id": "c", "text": "Adequate lighting and workspace.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M09.10'), 'What should an accident-prevention reference draw on?', '[{"id": "a", "text": "Only a few accidents with no analysis.", "correct": false}, {"id": "b", "text": "Accident and incident evidence, causal analysis and preventive lessons.", "correct": true}, {"id": "c", "text": "A guarantee that every accident has been recorded.", "correct": false}]'::jsonb, '{B1,B2}');
